import type { ConfigContext, ExpoConfig } from "expo/config";
import { z } from "zod";

const apiUrl = z
  .string()
  .url()
  .refine(
    (value) => value.startsWith("http://") || value.startsWith("https://"),
    "EXPO_PUBLIC_API_URL must use http or https"
  )
  .parse(process.env.EXPO_PUBLIC_API_URL);

export default ({ config }: ConfigContext): ExpoConfig => ({
  ...config,
  name: "鲜知 FreshTrack",
  slug: "freshtrack",
  version: "0.1.0",
  orientation: "portrait",
  scheme: "freshtrack",
  userInterfaceStyle: "light",
  platforms: ["android"],
  android: {
    package: "com.rowanxing.freshtrack"
  },
  plugins: [
    "expo-router",
    [
      "expo-notifications",
      {
        defaultChannel: "freshtrack-expiry-reminders"
      }
    ],
    [
      "expo-secure-store",
      {
        configureAndroidBackup: true
      }
    ]
  ],
  experiments: {
    typedRoutes: true
  },
  extra: {
    apiUrl,
    eas: {
      projectId: "f2fee7a0-00f2-4ad4-ac6b-31daf8f36faf"
    }
  }
});
import { z } from "zod";

const mobileEnvSchema = z.strictObject({
  EXPO_PUBLIC_API_URL: z
    .string()
    .url("API 地址无效")
    .refine(
      (value) => value.startsWith("http://") || value.startsWith("https://"),
      "API 地址必须使用 http 或 https"
    )
    .transform((value) => value.replace(/\/+$/, ""))
});

export type MobileEnv = z.infer<typeof mobileEnvSchema>;

let cachedEnv: MobileEnv | undefined;

export function getMobileEnv(): MobileEnv {
  cachedEnv ??= mobileEnvSchema.parse({
    EXPO_PUBLIC_API_URL: process.env.EXPO_PUBLIC_API_URL
  });
  return cachedEnv;
}

import {
  apiErrorSchema,
  authResponseSchema,
  meResponseSchema,
  type ApiErrorCode,
  type AuthCredentials,
  type AuthResponse,
  type MeResponse
} from "@freshtrack/contracts";
import type { z } from "zod";

import { getMobileEnv } from "../env";

export class ApiClientError extends Error {
  public constructor(
    message: string,
    public readonly code: ApiErrorCode | "NETWORK_ERROR" | "INVALID_RESPONSE",
    public readonly status?: number,
    public readonly fields?: Record<string, string[]>
  ) {
    super(message);
    this.name = "ApiClientError";
  }

  public get isInvalidSession(): boolean {
    return (
      this.code === "AUTH_REQUIRED" ||
      this.code === "AUTH_SESSION_EXPIRED" ||
      this.code === "AUTH_SESSION_INVALID"
    );
  }
}

async function parseResponse<T>(
  response: Response,
  schema: z.ZodType<T>
): Promise<T> {
  let body: unknown;
  try {
    body = await response.json();
  } catch {
    throw new ApiClientError(
      "服务器返回了无法识别的内容",
      "INVALID_RESPONSE",
      response.status
    );
  }

  if (!response.ok) {
    const error = apiErrorSchema.safeParse(body);
    if (!error.success) {
      throw new ApiClientError(
        "服务器返回了无法识别的错误",
        "INVALID_RESPONSE",
        response.status
      );
    }
    throw new ApiClientError(
      error.data.error.message,
      error.data.error.code,
      response.status,
      error.data.error.fields
    );
  }

  const parsed = schema.safeParse(body);
  if (!parsed.success) {
    throw new ApiClientError(
      "服务器数据格式不兼容，请稍后重试",
      "INVALID_RESPONSE",
      response.status
    );
  }
  return parsed.data;
}

export async function request<T>(
  path: string,
  schema: z.ZodType<T>,
  init: RequestInit
): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`${getMobileEnv().EXPO_PUBLIC_API_URL}${path}`, init);
  } catch {
    throw new ApiClientError(
      "无法连接服务器，请检查网络和 API 地址",
      "NETWORK_ERROR"
    );
  }
  return parseResponse(response, schema);
}

export function authorizationHeaders(token: string): HeadersInit {
  return {
    authorization: `Bearer ${token}`
  };
}

export async function requestEmpty(
  path: string,
  init: RequestInit
): Promise<void> {
  let response: Response;
  try {
    response = await fetch(`${getMobileEnv().EXPO_PUBLIC_API_URL}${path}`, init);
  } catch {
    throw new ApiClientError(
      "无法连接服务器，请检查网络和 API 地址",
      "NETWORK_ERROR"
    );
  }
  if (response.status === 204) {
    return;
  }
  await parseResponse(response, meResponseSchema);
}

export function register(credentials: AuthCredentials): Promise<AuthResponse> {
  return request("/v1/auth/register", authResponseSchema, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(credentials)
  });
}

export function login(credentials: AuthCredentials): Promise<AuthResponse> {
  return request("/v1/auth/login", authResponseSchema, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(credentials)
  });
}

export function me(token: string): Promise<MeResponse> {
  return request("/v1/auth/me", meResponseSchema, {
    method: "GET",
    headers: authorizationHeaders(token)
  });
}

export async function logout(token: string): Promise<void> {
  await requestEmpty("/v1/auth/logout", {
    method: "POST",
    headers: authorizationHeaders(token)
  });
}
import {
  foodCountsResponseSchema,
  foodListResponseSchema,
  foodResponseSchema,
  type Food,
  type FoodCounts,
  type FoodCreate,
  type FoodHistoryStatus,
  type FoodProcess,
  type FoodSegment,
  type FoodSort,
  type FoodUpdate
} from "@freshtrack/contracts";

import {
  authorizationHeaders,
  request,
  requestEmpty
} from "../auth/api";

export type FoodListParams =
  | {
      view: "active";
      search: string;
      category?: FoodCreate["category"];
      segment: FoodSegment;
      sort: FoodSort;
      today: string;
    }
  | {
      view: "history";
      search: string;
      category?: FoodCreate["category"];
      status: FoodHistoryStatus;
    };

function queryString(params: FoodListParams): string {
  const query = new URLSearchParams();
  query.set("view", params.view);
  query.set("search", params.search);
  if (params.category) {
    query.set("category", params.category);
  }
  if (params.view === "active") {
    query.set("segment", params.segment);
    query.set("sort", params.sort);
    if (params.segment !== "all") {
      query.set("today", params.today);
    }
  } else {
    query.set("status", params.status);
    query.set("sort", "created");
  }
  return query.toString();
}

function jsonHeaders(token: string): HeadersInit {
  return {
    ...authorizationHeaders(token),
    "content-type": "application/json"
  };
}

export async function listFoods(
  token: string,
  params: FoodListParams,
  signal?: AbortSignal
): Promise<Food[]> {
  const response = await request(
    `/v1/foods?${queryString(params)}`,
    foodListResponseSchema,
    {
      method: "GET",
      headers: authorizationHeaders(token),
      ...(signal ? { signal } : {})
    }
  );
  return response.items;
}

export async function listActiveFoodsForReminders(
  token: string,
  signal?: AbortSignal
): Promise<Food[]> {
  const response = await request(
    "/v1/foods/reminder-candidates",
    foodListResponseSchema,
    {
      method: "GET",
      headers: authorizationHeaders(token),
      ...(signal ? { signal } : {})
    }
  );
  return response.items;
}

export async function getFood(
  token: string,
  foodId: string,
  signal?: AbortSignal
): Promise<Food> {
  const response = await request(
    `/v1/foods/${encodeURIComponent(foodId)}`,
    foodResponseSchema,
    {
      method: "GET",
      headers: authorizationHeaders(token),
      ...(signal ? { signal } : {})
    }
  );
  return response.food;
}

export async function getFoodCounts(
  token: string,
  today: string,
  signal?: AbortSignal
): Promise<FoodCounts> {
  const response = await request(
    `/v1/foods/counts?today=${encodeURIComponent(today)}`,
    foodCountsResponseSchema,
    {
      method: "GET",
      headers: authorizationHeaders(token),
      ...(signal ? { signal } : {})
    }
  );
  return response.counts;
}

export async function createFood(
  token: string,
  input: FoodCreate
): Promise<Food> {
  const response = await request("/v1/foods", foodResponseSchema, {
    method: "POST",
    headers: jsonHeaders(token),
    body: JSON.stringify(input)
  });
  return response.food;
}

export async function updateFood(
  token: string,
  foodId: string,
  input: FoodUpdate
): Promise<Food> {
  const response = await request(
    `/v1/foods/${encodeURIComponent(foodId)}`,
    foodResponseSchema,
    {
      method: "PUT",
      headers: jsonHeaders(token),
      body: JSON.stringify(input)
    }
  );
  return response.food;
}

export function deleteFood(token: string, foodId: string): Promise<void> {
  return requestEmpty(`/v1/foods/${encodeURIComponent(foodId)}`, {
    method: "DELETE",
    headers: authorizationHeaders(token)
  });
}

export async function processFood(
  token: string,
  foodId: string,
  input: FoodProcess
): Promise<Food> {
  const response = await request(
    `/v1/foods/${encodeURIComponent(foodId)}/process`,
    foodResponseSchema,
    {
      method: "POST",
      headers: jsonHeaders(token),
      body: JSON.stringify(input)
    }
  );
  return response.food;
}

export async function restoreFood(
  token: string,
  foodId: string
): Promise<Food> {
  const response = await request(
    `/v1/foods/${encodeURIComponent(foodId)}/restore`,
    foodResponseSchema,
    {
      method: "POST",
      headers: authorizationHeaders(token)
    }
  );
  return response.food;
}

