import { describe, expect, it } from "vitest";

import { createAppConfig } from "./app.config";

const expectedPlugins = (enabled: boolean): NonNullable<
  ReturnType<typeof createAppConfig>["plugins"]
> => [
  "expo-router",
  [
    "expo-notifications",
    {
      defaultChannel: "freshtrack-expiry-reminders"
    }
  ],
  [
    "expo-secure-store",
    {
      configureAndroidBackup: true
    }
  ],
  [
    "./plugins/with-android-cleartext-traffic",
    {
      enabled
    }
  ]
];

describe("createAppConfig", () => {
  it("enables Android cleartext traffic for an HTTP API build", () => {
    const config = createAppConfig({}, "http://10.0.2.2:3000");

    expect(config.plugins).toEqual(expectedPlugins(true));
    expect(config.extra?.apiUrl).toBe("http://10.0.2.2:3000");
  });

  it("disables Android cleartext traffic for an HTTPS API build", () => {
    const config = createAppConfig({}, "https://api.freshtrack.example");

    expect(config.plugins).toEqual(expectedPlugins(false));
    expect(config.extra?.apiUrl).toBe("https://api.freshtrack.example");
  });
});
import {
  AndroidConfig,
  type AndroidManifest,
  type ConfigPlugin,
  withAndroidManifest
} from "expo/config-plugins";

export type AndroidCleartextTrafficOptions = {
  enabled: boolean;
};

export function setAndroidCleartextTraffic(
  manifest: AndroidManifest,
  enabled: boolean
): AndroidManifest {
  const application =
    AndroidConfig.Manifest.getMainApplicationOrThrow(manifest);
  application.$["android:usesCleartextTraffic"] = enabled ? "true" : "false";
  return manifest;
}

const withAndroidCleartextTraffic: ConfigPlugin<
  AndroidCleartextTrafficOptions
> = (config, { enabled }) =>
  withAndroidManifest(config, (modConfig) => {
    setAndroidCleartextTraffic(modConfig.modResults, enabled);
    return modConfig;
  });

export default withAndroidCleartextTraffic;
import {
  AndroidConfig,
  type AndroidManifest
} from "expo/config-plugins";
import { describe, expect, it } from "vitest";

import { setAndroidCleartextTraffic } from "./with-android-cleartext-traffic";

function createManifest(): AndroidManifest {
  return {
    manifest: {
      $: {
        "xmlns:android": "http://schemas.android.com/apk/res/android"
      },
      queries: [],
      application: [
        {
          $: {
            "android:name": ".MainApplication"
          }
        }
      ]
    }
  };
}

describe("setAndroidCleartextTraffic", () => {
  it.each([
    [true, "true"],
    [false, "false"]
  ] as const)(
    "writes android:usesCleartextTraffic=%s to the main application",
    (enabled, expected) => {
      const manifest = setAndroidCleartextTraffic(createManifest(), enabled);
      const application = AndroidConfig.Manifest.getMainApplication(manifest);

      expect(application?.$["android:usesCleartextTraffic"]).toBe(expected);
    }
  );
});

